  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']
    # Build edges with mutual reachability
    edges = []
    for a, b, d in distances:
        w = max(core_distance[a], core_distance[b], d)
        # canonicalize order
        if a < b:
            edges.append((w, a, b))
        else:
            edges.append((w, b, a))
    # Sort by weight, then lexicographically by node ids
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Disjoint-set union
    node_to_index = {node: i for i, node in enumerate(nodes)}
    parent = list(range(len(nodes)))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        parent[ry] = rx
        return True
    mst_edges = []
    total_weight = 0.0
    for w, a, b in edges:
        if union(node_to_index[a], node_to_index[b]):
            mst_edges.append([a, b, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Input graph is disconnected; cannot compute MST')
    return {'mst_edges': mst_edges, 'total_weight': total_weight}"
}
